26	// One mmap per event keeps source lifetimes explicit without the large-tail
27	// regression observed when many shard mappings stay live together.
28	const MMAP_EVENT_GROUP: usize = 1;
29	const LIVE_MMAP_GROUPS: usize = 16;
30	enum WeightUploader {
31	    Pageable,
32	    Staged(Glm52WeightStager),
33	}
34	
35	impl WeightUploader {
36	    fn new(ctx: &Glm52RankGpuContext, rank: usize, weight_staging: bool) -> Result<Self> {
37	        if weight_staging {
38	            Ok(Self::Staged(Glm52WeightStager::new(ctx, rank)?))
39	        } else {
40	            Ok(Self::Pageable)
41	        }
42	    }
43	
44	    fn label(&self) -> &'static str {
45	        match self {
46	            Self::Pageable => "pageable",
47	            Self::Staged(_) => "pinned",
48	        }
49	    }
50	
51	    fn upload(
52	        &mut self,
53	        ctx: &Glm52RankGpuContext,
54	        src: &[u8],
55	        dst: &mut CudaSlice<u8>,
56	        dst_offset: usize,
57	    ) -> Result<usize> {
58	        match self {
59	            Self::Pageable => {
60	                let end = dst_offset.checked_add(src.len()).ok_or_else(|| {
61	                    anyhow::anyhow!("GLM5.2 pageable upload destination range overflow")
62	                })?;
63	                ensure!(
64	                    end <= dst.len(),
65	                    "GLM5.2 pageable upload [{dst_offset}..{end}) exceeds destination of {} bytes",
66	                    dst.len()
67	                );
68	                let mut view = dst.slice_mut(dst_offset..end);
69	                ctx.stream()
70	                    .memcpy_htod(src, &mut view)
71	                    .context("GLM5.2 pageable H2D copy")?;
72	                Ok(1)
73	            }
74	            Self::Staged(stager) => stager.upload(src, dst, dst_offset),
75	        }
76	    }
77	}
78	
79	/// One layer's rank-local routed experts, packed expert-major at H2D time
80	/// (per expert: [gate; up] fp8 rows / f32 scales; down alone) — the exact
81	/// layout `Glm52MoeExpertBank` consumes, so `from_device` is a move.
82	pub(crate) struct Glm52ExpertLayerRegions {
83	    pub(crate) w13_weight: CudaSlice<u8>,
84	    pub(crate) w13_scale: CudaSlice<u8>,
85	    pub(crate) w2_weight: CudaSlice<u8>,
86	    pub(crate) w2_scale: CudaSlice<u8>,
87	}
88	
89	impl Glm52ExpertLayerRegions {
90	    fn alloc(ctx: &Glm52RankGpuContext, local_experts: usize) -> Result<Self> {
91	        // SAFETY: every byte of every region is written exactly once from a
92	        // validated safetensors view; the coverage counters below fail the
93	        // load if any byte is left unwritten.
94	        let alloc = |kind: Glm52ExpertRegionKind| -> Result<CudaSlice<u8>> {
95	            unsafe { ctx.stream().alloc::<u8>(kind.region_bytes(local_experts)) }
96	                .with_context(|| format!("alloc GLM5.2 expert region {kind:?}"))
97	        };
98	        Ok(Self {
99	            w13_weight: alloc(Glm52ExpertRegionKind::W13Weight)?,
100	            w13_scale: alloc(Glm52ExpertRegionKind::W13Scale)?,
101	            w2_weight: alloc(Glm52ExpertRegionKind::W2Weight)?,
102	            w2_scale: alloc(Glm52ExpertRegionKind::W2Scale)?,
103	        })
104	    }
105	
106	    fn region_mut(&mut self, kind: Glm52ExpertRegionKind) -> &mut CudaSlice<u8> {
107	        match kind {
108	            Glm52ExpertRegionKind::W13Weight => &mut self.w13_weight,
109	            Glm52ExpertRegionKind::W13Scale => &mut self.w13_scale,
110	            Glm52ExpertRegionKind::W2Weight => &mut self.w2_weight,
111	            Glm52ExpertRegionKind::W2Scale => &mut self.w2_scale,
112	        }
113	    }
114	}
115	
116	/// Rank-resident weights: every non-expert tensor as its own device buffer
117	/// (raw checkpoint bytes), plus the per-layer packed expert regions.
118	/// `from_device` constructors take entries out of these maps.
119	pub(crate) struct Glm52RankGpuWeights {
120	    tensors: BTreeMap<String, CudaSlice<u8>>,
121	    expert_layers: BTreeMap<usize, Glm52ExpertLayerRegions>,
122	    pub(crate) total_bytes: usize,
123	}
124	
125	impl Glm52RankGpuWeights {
126	    /// Remove and return one non-expert tensor buffer (raw checkpoint bytes).
127	    pub(crate) fn take_tensor(&mut self, name: &str) -> Result<CudaSlice<u8>> {
128	        self.tensors
129	            .remove(name)
130	            .ok_or_else(|| anyhow::anyhow!("GLM5.2 resident weights missing tensor {name}"))
131	    }
132	
133	    /// Remove and return one layer's packed expert regions.
134	    pub(crate) fn take_expert_layer(&mut self, layer: usize) -> Result<Glm52ExpertLayerRegions> {
135	        self.expert_layers.remove(&layer).ok_or_else(|| {
136	            anyhow::anyhow!("GLM5.2 resident weights missing expert regions for layer {layer}")
137	        })
138	    }
139	
140	    /// Every resident load-plan entry must move into the built model. Keeping
141	    /// validation-only tensors in these maps silently spends H2D bandwidth
142	    /// and transient HBM before dropping them with the load bundle.
143	    pub(crate) fn ensure_consumed(&self) -> Result<()> {
144	        let tensor_sample = self.tensors.keys().take(5).cloned().collect::<Vec<_>>();
145	        let expert_sample = self
146	            .expert_layers
147	            .keys()
148	            .take(5)
149	            .copied()
150	            .collect::<Vec<_>>();
151	        ensure!(
152	            self.tensors.is_empty() && self.expert_layers.is_empty(),
153	            "GLM5.2 resident load plan contains tensors the model did not consume: \
154	             tensors={} sample={tensor_sample:?}, expert_layers={} sample={expert_sample:?}",
155	            self.tensors.len(),
156	            self.expert_layers.len(),
157	        );
158	        Ok(())
159	    }
160	}
161	
162	pub(crate) struct Glm52RankLoadOutput {
163	    pub(crate) weights: Glm52RankGpuWeights,
164	    pub(crate) loaded_tensor_count: usize,
165	    pub(crate) loaded_total_bytes: usize,
166	}
167	
168	pub(crate) fn load_rank_weights_to_gpu(
169	    ctx: &Glm52RankGpuContext,
170	    model_path: &Path,
171	    bundle: &Glm52RankLoadBundle,
172	    weight_staging: bool,
173	) -> Result<Glm52RankLoadOutput> {
174	    ctx.set_current()?;
175	    let load_started = Instant::now();
176	    let planned_total_bytes = bundle.planned_total_bytes()?;
177	
178	    let mut weights = Glm52RankGpuWeights {
179	        tensors: BTreeMap::new(),
180	        expert_layers: BTreeMap::new(),
181	        total_bytes: 0,
182	    };
183	    // Bytes written per (layer, region): the coverage proof that packed
184	    // placement filled every region exactly.
185	    let mut region_written: BTreeMap<(usize, Glm52ExpertRegionKind), usize> = BTreeMap::new();
186	    let mut loaded_tensor_count = 0usize;
187	    let mut loaded_total_bytes = 0usize;
188	    let copy_started = Instant::now();
189	    let mut slowest_shard: Option<(String, f64)> = None;
190	    let mut h2d_copies = 0usize;
191	    let mut mmap_guard = MmapH2dLifetimeGuard::new(ctx, bundle.plan.rank);
192	    let mut sync_secs = 0.0f64;
193	    let mut uploader = WeightUploader::new(ctx, bundle.plan.rank, weight_staging)?;
194	    debug!(
195	        "GLM5.2 rank {} start weight load: tensors={}, shards={}, bytes={}, experts={:?}, uploader={}",
196	        bundle.plan.rank,
197	        bundle.plan.tensor_count,
198	        bundle.shards.len(),
199	        ByteSize(planned_total_bytes as u64),
200	        bundle.plan.expert_range,
201	        uploader.label(),
202	    );
203	
204	    for shard in &bundle.shards {
205	        let path = model_path.join(&shard.shard);
206	        let shard_started = Instant::now();
207	        let mmap = CurrentShardMmap::new(mmap_file(&path)?, ctx, bundle.plan.rank);
208	        let safetensors = safetensors::SafeTensors::deserialize(mmap.as_ref())
209	            .with_context(|| format!("failed to deserialize {}", path.display()))?;
210	        for spec in &shard.tensors {
211	            let view = safetensors
212	                .tensor(&spec.name)
213	                .with_context(|| format!("missing tensor {} in {}", spec.name, path.display()))?;
214	            let contract = expected_tensor_contract(&spec.name)?;
215	            ensure!(
216	                view.dtype() == contract.dtype,
217	                "GLM5.2 tensor {} dtype mismatch: got {:?}, expected {:?}",
218	                spec.name,
219	                view.dtype(),
220	                contract.dtype
221	            );
222	            ensure!(
223	                view.shape() == contract.shape.as_slice(),
224	                "GLM5.2 tensor {} shape mismatch: got {:?}, expected {:?}",
225	                spec.name,
226	                view.shape(),
227	                contract.shape
228	            );
229	            let bytes = view.data().len();
230	            ensure!(
231	                bytes == contract.byte_len()?,
232	                "GLM5.2 tensor {} byte mismatch: got {}, expected {}",
233	                spec.name,
234	                bytes,
235	                contract.byte_len()?
236	            );
237	
238	            if let Some(placement) = expert_placement(&spec.name, &bundle.plan.expert_range)? {
239	                let regions = match weights.expert_layers.entry(placement.layer) {
240	                    std::collections::btree_map::Entry::Occupied(entry) => entry.into_mut(),
241	                    std::collections::btree_map::Entry::Vacant(entry) => entry.insert(
242	                        Glm52ExpertLayerRegions::alloc(ctx, bundle.plan.expert_range.len())?,
243	                    ),
244	                };
245	                let region = regions.region_mut(placement.region);
246	                ensure!(
247	                    placement.offset + bytes <= region.len(),
248	                    "GLM5.2 tensor {} placement [{}..{}) exceeds region {:?} ({} bytes)",
249	                    spec.name,
250	                    placement.offset,
251	                    placement.offset + bytes,
252	                    placement.region,
253	                    region.len()
254	                );
255	                mmap.mark_stream_work();
256	                h2d_copies += uploader
257	                    .upload(ctx, view.data(), region, placement.offset)
258	                    .with_context(|| {
259	                        format!("failed to copy GLM5.2 expert tensor {} to GPU", spec.name)
260	                    })?;
261	                *region_written
262	                    .entry((placement.layer, placement.region))
263	                    .or_default() += bytes;
264	            } else {
265	                // SAFETY: the whole buffer is written by the single H2D copy
266	                // below before it becomes reachable resident state.
267	                let mut dst = unsafe { ctx.stream().alloc::<u8>(bytes) }
268	                    .with_context(|| format!("alloc GLM5.2 tensor {}", spec.name))?;
269	                mmap.mark_stream_work();
270	                h2d_copies += uploader
271	                    .upload(ctx, view.data(), &mut dst, 0)
272	                    .with_context(|| {
273	                        format!("failed to copy GLM5.2 tensor {} to GPU", spec.name)
274	                    })?;
275	                ensure!(
276	                    weights.tensors.insert(spec.name.clone(), dst).is_none(),
277	                    "duplicate GLM5.2 tensor {} in rank {} load plan",
278	                    spec.name,
279	                    bundle.plan.rank,
280	                );
281	            }
282	            weights.total_bytes += bytes;
283	            loaded_total_bytes += bytes;
284	            loaded_tensor_count += 1;
285	        }
286	        drop(safetensors);
287	        sync_secs += mmap_guard.push_completed_shard(mmap.into_mmap())?;
288	        let shard_secs = shard_started.elapsed().as_secs_f64();
289	        match &slowest_shard {
290	            Some((_, slowest_secs)) if *slowest_secs >= shard_secs => {}
291	            _ => slowest_shard = Some((shard.shard.clone(), shard_secs)),
292	        }
293	    }
294	
295	    ensure!(
296	        loaded_tensor_count == bundle.plan.tensor_count,
297	        "GLM5.2 rank {} loaded {loaded_tensor_count} tensors but load plan has {}",
298	        bundle.plan.rank,
299	        bundle.plan.tensor_count
300	    );
301	    ensure!(
302	        loaded_total_bytes == planned_total_bytes,
303	        "GLM5.2 rank {} loaded {} bytes but load plan has {} bytes",
304	        bundle.plan.rank,
305	        loaded_total_bytes,
306	        planned_total_bytes
307	    );
308	    // Every packed expert region must be fully written — a hole here means
309	    // stale device bytes would silently become model weights.
310	    for layer in weights.expert_layers.keys() {
311	        for kind in Glm52ExpertRegionKind::ALL {
312	            let written = region_written.get(&(*layer, kind)).copied().unwrap_or(0);
313	            let expected = kind.region_bytes(bundle.plan.expert_range.len());
314	            ensure!(
315	                written == expected,
316	                "GLM5.2 rank {} layer {layer} expert region {kind:?} incomplete: wrote {written} of {expected} bytes",
317	                bundle.plan.rank
318	            );
319	        }
320	    }
321	    sync_secs += mmap_guard.drain()?;
322	    let uploader_label = uploader.label();
323	    let uploader_drop_started = Instant::now();
324	    drop(uploader);
325	    sync_secs += uploader_drop_started.elapsed().as_secs_f64();
326	    let copy_secs = (copy_started.elapsed().as_secs_f64() - sync_secs).max(0.0);
327	    let sync_started = Instant::now();
328	    ctx.sync().with_context(|| {
329	        format!(
330	            "failed to finish GLM5.2 rank {} H2D tensor copies",
331	            bundle.plan.rank
332	        )
333	    })?;
334	    sync_secs += sync_started.elapsed().as_secs_f64();
335	
336	    let (slowest_shard, slowest_secs) = slowest_shard.unwrap_or_else(|| ("none".to_owned(), 0.0));
337	    info!(
338	        "GLM5.2 rank {} weight load profile: total={:.2}s, mmap_deser_copy={:.2}s, sync={:.2}s, uploader={}, tensors={}, h2d_copies={}, bytes={}, expert_layers={}, slowest_shard={} {:.2}s",
339	        bundle.plan.rank,
340	        load_started.elapsed().as_secs_f64(),
341	        copy_secs,
342	        sync_secs,
343	        uploader_label,
344	        loaded_tensor_count,
345	        h2d_copies,
346	        ByteSize(loaded_total_bytes as u64),
347	        weights.expert_layers.len(),
348	        slowest_shard,
349	        slowest_secs
350	    );
351	
352	    Ok(Glm52RankLoadOutput {
353	        weights,
354	        loaded_tensor_count,
355	        loaded_total_bytes,
356	    })
357	}
358	
359	struct LiveMmapGroup {
360	    _mmaps: Vec<Mmap>,
361	    event: CudaEvent,
362	}
363	
364	struct CurrentShardMmap<'a> {
365	    mmap: Option<Mmap>,
366	    ctx: &'a Glm52RankGpuContext,
367	    rank: usize,
368	    stream_work: Cell<bool>,
369	}
370	
371	impl<'a> CurrentShardMmap<'a> {
372	    fn new(mmap: Mmap, ctx: &'a Glm52RankGpuContext, rank: usize) -> Self {
373	        Self {
374	            mmap: Some(mmap),
375	            ctx,
376	            rank,
377	            stream_work: Cell::new(false),
378	        }
379	    }
380	
381	    fn as_ref(&self) -> &Mmap {
382	        self.mmap.as_ref().expect("current shard mmap is present")
383	    }
384	
385	    fn mark_stream_work(&self) {
386	        self.stream_work.set(true);
387	    }
388	
389	    fn into_mmap(mut self) -> Mmap {
390	        self.stream_work.set(false);
391	        self.mmap.take().expect("current shard mmap is present")
392	    }
393	}
394	
395	impl Drop for CurrentShardMmap<'_> {
396	    fn drop(&mut self) {
397	        if self.stream_work.get() {
398	            if let Err(error) = self.ctx.set_current().and_then(|()| self.ctx.sync()) {
399	                error!(
400	                    "failed to synchronize GLM5.2 rank {} before dropping current H2D mmap: {error:#}",
401	                    self.rank
402	                );
403	            }
404	        }
405	    }
406	}
407	
408	struct MmapH2dLifetimeGuard<'a> {
409	    ctx: &'a Glm52RankGpuContext,
410	    rank: usize,
411	    pending_mmaps: Vec<Mmap>,
412	    live_mmap_groups: VecDeque<LiveMmapGroup>,
413	}
414	
415	impl<'a> MmapH2dLifetimeGuard<'a> {
416	    fn new(ctx: &'a Glm52RankGpuContext, rank: usize) -> Self {
417	        Self {
418	            ctx,
419	            rank,
420	            pending_mmaps: Vec::with_capacity(MMAP_EVENT_GROUP),
421	            live_mmap_groups: VecDeque::with_capacity(LIVE_MMAP_GROUPS),
422	        }
423	    }
424	
425	    fn push_completed_shard(&mut self, mmap: Mmap) -> Result<f64> {
426	        self.pending_mmaps.push(mmap);
427	        let mut sync_secs = 0.0;
428	        if self.pending_mmaps.len() == MMAP_EVENT_GROUP {
429	            self.record_pending_group()?;
430	        }
431	        if self.live_mmap_groups.len() >= LIVE_MMAP_GROUPS {
432	            sync_secs += self.wait_oldest_group()?;
433	        }
434	        Ok(sync_secs)
435	    }
436	
437	    fn drain(&mut self) -> Result<f64> {
438	        let mut sync_secs = 0.0;
439	        if !self.pending_mmaps.is_empty() {
440	            self.record_pending_group()?;
441	        }
442	        while !self.live_mmap_groups.is_empty() {
443	            sync_secs += self.wait_oldest_group()?;
444	        }
445	        Ok(sync_secs)
446	    }
447	
448	    fn record_pending_group(&mut self) -> Result<()> {
449	        let event = self.ctx.stream().record_event(None).with_context(|| {
450	            format!(
451	                "failed to record GLM5.2 rank {} H2D mmap group event",
452	                self.rank
453	            )
454	        })?;
455	        let mut mmaps = Vec::with_capacity(MMAP_EVENT_GROUP);
456	        std::mem::swap(&mut self.pending_mmaps, &mut mmaps);
457	        self.live_mmap_groups.push_back(LiveMmapGroup {
458	            _mmaps: mmaps,
459	            event,
460	        });
461	        Ok(())
462	    }
463	
464	    fn wait_oldest_group(&mut self) -> Result<f64> {
465	        let Some(live) = self.live_mmap_groups.front() else {
466	            return Ok(0.0);
467	        };
468	        let started = Instant::now();
469	        live.event.synchronize().with_context(|| {
470	            format!(
471	                "failed to wait for GLM5.2 rank {} H2D mmap event",
472	                self.rank
473	            )
474	        })?;
475	        self.live_mmap_groups.pop_front();
476	        Ok(started.elapsed().as_secs_f64())
477	    }
478	}
479	
480	impl Drop for MmapH2dLifetimeGuard<'_> {
481	    fn drop(&mut self) {
482	        if self.pending_mmaps.is_empty() && self.live_mmap_groups.is_empty() {
483	            return;
484	        }
485	        if let Err(error) = self.ctx.set_current().and_then(|()| self.ctx.sync()) {
486	            error!(
487	                "failed to synchronize GLM5.2 rank {} before dropping H2D mmap guard: {error:#}",
488	                self.rank
489	            );
490	        }
491	    }
492	}
