18	
19	/// Bytes per pinned slot. Two slots cost 64 MiB/rank (256 MiB for EP4) and
20	/// allow one host fill to overlap one H2D DMA. See the GLM5.2 GB300 bring-up
21	/// document for the same-host EP4 parameter sweep behind this value.
22	const STAGE_BYTES: usize = 32 << 20;
23	/// Persistent host memcpy workers per rank. EP4 has 30,660 uploads/rank;
24	/// retaining the workers avoids repeated thread creation and yields 16 active
25	/// fill workers across four local ranks. See the GLM5.2 GB300 bring-up
26	/// document for the same-host EP4 parameter sweep behind this value.
27	const FILL_THREADS: usize = 4;
28	/// Expert scale tensors are only 3 KiB; channel fan-out costs more than their
29	/// memcpy. Large projections still use all persistent workers.
30	const PARALLEL_FILL_MIN_BYTES: usize = 1 << 20;
31	
32	struct StagingBuf {
33	    pinned: PinnedHostSlice<u8>,
34	    dma_done: CudaEvent,
35	}
36	
37	struct FillPool {
38	    pool: ThreadPool,
39	    workers: usize,
40	}
41	
42	impl FillPool {
43	    fn new(rank: usize) -> Result<Self> {
44	        let pool = ThreadPoolBuilder::new()
45	            .num_threads(FILL_THREADS)
46	            .thread_name(move |worker| format!("glm52-weight-fill-{rank}-{worker}"))
47	            .build()
48	            .with_context(|| format!("build GLM5.2 rank {rank} weight-fill pool"))?;
49	        Ok(Self {
50	            pool,
51	            workers: FILL_THREADS,
52	        })
53	    }
54	
55	    /// Copy `src` into a same-sized destination using persistent workers.
56	    fn fill(&self, src: &[u8], dst: &mut [u8]) {
57	        debug_assert_eq!(src.len(), dst.len());
58	        if src.is_empty() {
59	            return;
60	        }
61	        if src.len() < PARALLEL_FILL_MIN_BYTES {
62	            dst.copy_from_slice(src);
63	            return;
64	        }
65	        let per = src.len().div_ceil(self.workers);
66	        self.pool.scope(|scope| {
67	            for (src_part, dst_part) in src.chunks(per).zip(dst.chunks_mut(per)) {
68	                scope.spawn(move |_| {
69	                    dst_part.copy_from_slice(src_part);
70	                });
71	            }
72	        });
73	    }
74	}
75	
76	#[cfg(test)]
77	impl FillPool {
78	    fn worker_count(&self) -> usize {
79	        self.workers
80	    }
81	}
82	
83	/// Pinned double-buffering overlaps mmap/page-cache reads with the preceding
84	/// buffer's H2D DMA. All GLM5.2 checkpoint tensors are carried as raw bytes,
85	/// so one uploader serves FP8, BF16, and F32 payloads without reinterpretation.
86	pub(crate) struct Glm52WeightStager {
87	    stream: Arc<CudaStream>,
88	    bufs: [StagingBuf; 2],
89	    fill: FillPool,
90	    next: usize,
91	}
92	
93	impl Glm52WeightStager {
94	    pub(crate) fn new(ctx: &Glm52RankGpuContext, rank: usize) -> Result<Self> {
95	        let make = || -> Result<StagingBuf> {
96	            // SAFETY: every byte consumed by DMA is initialized by the fill
97	            // pool first; buffer reuse is gated by `dma_done`.
98	            let pinned = unsafe { ctx.cuda_context().alloc_pinned::<u8>(STAGE_BYTES) }
99	                .context("alloc GLM5.2 pinned weight staging buffer")?;
100	            let dma_done = ctx
101	                .cuda_context()
102	                .new_event(Some(CUevent_flags::CU_EVENT_BLOCKING_SYNC))
103	                .context("create GLM5.2 pinned weight staging event")?;
104	            Ok(StagingBuf { pinned, dma_done })
105	        };
106	        Ok(Self {
107	            stream: ctx.stream().clone(),
108	            bufs: [make()?, make()?],
109	            fill: FillPool::new(rank)?,
110	            next: 0,
111	        })
112	    }
113	
114	    /// Upload `src` into raw device bytes starting at `dst_offset`.
115	    pub(crate) fn upload(
116	        &mut self,
117	        src: &[u8],
118	        dst: &mut CudaSlice<u8>,
119	        dst_offset: usize,
120	    ) -> Result<usize> {
121	        ensure!(
122	            Arc::ptr_eq(dst.stream(), &self.stream),
123	            "GLM5.2 staged upload destination was allocated on a different stream"
124	        );
125	        ensure!(
126	            dst_offset
127	                .checked_add(src.len())
128	                .is_some_and(|end| end <= dst.len()),
129	            "GLM5.2 staged upload [{}..{}) exceeds destination of {} bytes",
130	            dst_offset,
131	            dst_offset.saturating_add(src.len()),
132	            dst.len()
133	        );
134	        let stream = self.stream.clone();
135	        let (dst_ptr, _dst_order) = dst.device_ptr_mut(&stream);
136	        let mut copies = 0usize;
137	        for (chunk_idx, chunk) in src.chunks(STAGE_BYTES).enumerate() {
138	            let dst_at = dst_ptr + (dst_offset + chunk_idx * STAGE_BYTES) as u64;
139	            // SAFETY: chunks partition the source, and the entry bound proves
140	            // the corresponding destination range is writable.
141	            unsafe { self.stage_chunk(chunk, dst_at) }?;
142	            copies += 1;
143	        }
144	        Ok(copies)
145	    }
146	
147	    /// # Safety
148	    /// `dst_at` must address `src.len() <= STAGE_BYTES` writable device bytes
149	    /// on the stager stream.
150	    unsafe fn stage_chunk(&mut self, src: &[u8], dst_at: u64) -> Result<()> {
151	        let idx = self.next;
152	        self.next = (self.next + 1) % self.bufs.len();
153	        let buf = &mut self.bufs[idx];
154	        buf.dma_done
155	            .synchronize()
156	            .context("drain GLM5.2 pinned staging buffer")?;
157	        let stage = buf
158	            .pinned
159	            .as_mut_slice()
160	            .context("get GLM5.2 pinned staging slice")?;
161	        let stage = &mut stage[..src.len()];
162	        self.fill.fill(src, stage);
163	        // SAFETY: the fill completed synchronously, the pinned allocation
164	        // outlives the DMA, and `dst_at` satisfies this function's contract.
165	        let copied = unsafe { memcpy_htod_async(dst_at, stage, self.stream.cu_stream()) };
166	        if let Err(copy_err) = copied {
167	            drain_or_abort(
168	                &self.stream,
169	                &format!("GLM5.2 staged H2D copy failed ({copy_err})"),
170	            );
171	            return Err(anyhow::anyhow!("GLM5.2 staged H2D copy failed: {copy_err}"));
172	        }
173	        if let Err(record_err) = buf.dma_done.record(&self.stream) {
174	            drain_or_abort(
175	                &self.stream,
176	                &format!("GLM5.2 staging event record failed ({record_err})"),
177	            );
178	            return Err(anyhow::anyhow!(
179	                "GLM5.2 staging event record failed: {record_err}"
180	            ));
181	        }
182	        Ok(())
183	    }
184	}
185	
186	impl Drop for Glm52WeightStager {
187	    fn drop(&mut self) {
188	        for buf in &self.bufs {
189	            if let Err(err) = buf.dma_done.synchronize() {
190	                error!(
191	                    "GLM5.2 staging DMA drain failed on drop ({err}); aborting instead of freeing pinned memory under an in-flight DMA"
192	                );
193	                std::process::abort();
194	            }
195	        }
196	    }
197	}
198	
199	fn drain_or_abort(stream: &CudaStream, context: &str) {
200	    if let Err(sync_err) = stream.synchronize() {
201	        error!(
202	            "{context}; stream drain failed ({sync_err}); aborting instead of freeing pinned memory under an in-flight DMA"
203	        );
204	        std::process::abort();
205	    }
206	}
207	
208	#[cfg(test)]
