211	
212	    #[test]
213	    fn persistent_fill_pool_copies_exact_bytes() -> Result<()> {
214	        let pool = FillPool::new(99)?;
215	        assert_eq!(pool.worker_count(), FILL_THREADS);
216	        for len in [0usize, 1, 3, 4095, 4096, 1 << 20, (3 << 20) + 17] {
217	            let src = (0..len).map(|i| (i % 251) as u8).collect::<Vec<_>>();
218	            let mut dst = vec![0xa5; len];
219	            pool.fill(&src, &mut dst);
220	            assert_eq!(dst, src, "persistent fill mismatch at len={len}");
221	        }
222	        Ok(())
223	    }
224	}
