26	// One mmap per event keeps source lifetimes explicit without the large-tail
27	// regression observed when many shard mappings stay live together.
28	const MMAP_EVENT_GROUP: usize = 1;
29	const LIVE_MMAP_GROUPS: usize = 16;
30	enum WeightUploader {
31	    Pageable,
32	    Staged(Glm52WeightStager),
33	}
34	
35	impl WeightUploader {
36	    fn new(ctx: &Glm52RankGpuContext, rank: usize, weight_staging: bool) -> Result<Self> {
37	        if weight_staging {
38	            Ok(Self::Staged(Glm52WeightStager::new(ctx, rank)?))
39	        } else {
40	            Ok(Self::Pageable)
41	        }
42	    }
43	
44	    fn label(&self) -> &'static str {
45	        match self {
46	            Self::Pageable => "pageable",
47	            Self::Staged(_) => "pinned",
48	        }
49	    }
50	
51	    fn upload(
52	        &mut self,
53	        ctx: &Glm52RankGpuContext,
54	        src: &[u8],
55	        dst: &mut CudaSlice<u8>,
56	        dst_offset: usize,
57	    ) -> Result<usize> {
58	        match self {
59	            Self::Pageable => {
60	                let end = dst_offset.checked_add(src.len()).ok_or_else(|| {
61	                    anyhow::anyhow!("GLM5.2 pageable upload destination range overflow")
62	                })?;
63	                ensure!(
64	                    end <= dst.len(),
65	                    "GLM5.2 pageable upload [{dst_offset}..{end}) exceeds destination of {} bytes",
66	                    dst.len()
67	                );
68	                let mut view = dst.slice_mut(dst_offset..end);
69	                ctx.stream()
70	                    .memcpy_htod(src, &mut view)
71	                    .context("GLM5.2 pageable H2D copy")?;
72	                Ok(1)
73	            }
74	            Self::Staged(stager) => stager.upload(src, dst, dst_offset),
75	        }
76	    }
77	}
78	
79	/// One layer's rank-local routed experts, packed expert-major at H2D time
80	/// (per expert: [gate; up] fp8 rows / f32 scales; down alone) — the exact
81	/// layout `Glm52MoeExpertBank` consumes, so `from_device` is a move.
82	pub(crate) struct Glm52ExpertLayerRegions {
83	    pub(crate) w13_weight: CudaSlice<u8>,
84	    pub(crate) w13_scale: CudaSlice<u8>,
85	    pub(crate) w2_weight: CudaSlice<u8>,
86	    pub(crate) w2_scale: CudaSlice<u8>,
87	}
88	
89	impl Glm52ExpertLayerRegions {
90	    fn alloc(ctx: &Glm52RankGpuContext, local_experts: usize) -> Result<Self> {
91	        // SAFETY: every byte of every region is written exactly once from a
92	        // validated safetensors view; the coverage counters below fail the
93	        // load if any byte is left unwritten.
94	        let alloc = |kind: Glm52ExpertRegionKind| -> Result<CudaSlice<u8>> {
95	            unsafe { ctx.stream().alloc::<u8>(kind.region_bytes(local_experts)) }
96	                .with_context(|| format!("alloc GLM5.2 expert region {kind:?}"))
97	        };
98	        Ok(Self {
99	            w13_weight: alloc(Glm52ExpertRegionKind::W13Weight)?,
100	            w13_scale: alloc(Glm52ExpertRegionKind::W13Scale)?,
101	            w2_weight: alloc(Glm52ExpertRegionKind::W2Weight)?,
102	            w2_scale: alloc(Glm52ExpertRegionKind::W2Scale)?,
103	        })
104	    }
105	
106	    fn region_mut(&mut self, kind: Glm52ExpertRegionKind) -> &mut CudaSlice<u8> {
107	        match kind {
108	            Glm52ExpertRegionKind::W13Weight => &mut self.w13_weight,
109	            Glm52ExpertRegionKind::W13Scale => &mut self.w13_scale,
110	            Glm52ExpertRegionKind::W2Weight => &mut self.w2_weight,
111	            Glm52ExpertRegionKind::W2Scale => &mut self.w2_scale,
112	        }
113	    }
114	}
115	
116	/// Rank-resident weights: every non-expert tensor as its own device buffer
117	/// (raw checkpoint bytes), plus the per-layer packed expert regions.
118	/// `from_device` constructors take entries out of these maps.
119	pub(crate) struct Glm52RankGpuWeights {
120	    tensors: BTreeMap<String, CudaSlice<u8>>,
121	    expert_layers: BTreeMap<usize, Glm52ExpertLayerRegions>,
122	    pub(crate) total_bytes: usize,
123	}
124	
125	impl Glm52RankGpuWeights {
126	    /// Remove and return one non-expert tensor buffer (raw checkpoint bytes).
127	    pub(crate) fn take_tensor(&mut self, name: &str) -> Result<CudaSlice<u8>> {
128	        self.tensors
129	            .remove(name)
130	            .ok_or_else(|| anyhow::anyhow!("GLM5.2 resident weights missing tensor {name}"))
131	    }
132	
133	    /// Remove and return one layer's packed expert regions.
134	    pub(crate) fn take_expert_layer(&mut self, layer: usize) -> Result<Glm52ExpertLayerRegions> {
135	        self.expert_layers.remove(&layer).ok_or_else(|| {
136	            anyhow::anyhow!("GLM5.2 resident weights missing expert regions for layer {layer}")
137	        })
138	    }
