168	pub(crate) fn load_rank_weights_to_gpu(
169	    ctx: &Glm52RankGpuContext,
170	    model_path: &Path,
171	    bundle: &Glm52RankLoadBundle,
172	    weight_staging: bool,
173	) -> Result<Glm52RankLoadOutput> {
174	    ctx.set_current()?;
175	    let load_started = Instant::now();
176	    let planned_total_bytes = bundle.planned_total_bytes()?;
177	
178	    let mut weights = Glm52RankGpuWeights {
179	        tensors: BTreeMap::new(),
180	        expert_layers: BTreeMap::new(),
181	        total_bytes: 0,
182	    };
183	    // Bytes written per (layer, region): the coverage proof that packed
184	    // placement filled every region exactly.
185	    let mut region_written: BTreeMap<(usize, Glm52ExpertRegionKind), usize> = BTreeMap::new();
186	    let mut loaded_tensor_count = 0usize;
187	    let mut loaded_total_bytes = 0usize;
188	    let copy_started = Instant::now();
189	    let mut slowest_shard: Option<(String, f64)> = None;
190	    let mut h2d_copies = 0usize;
191	    let mut mmap_guard = MmapH2dLifetimeGuard::new(ctx, bundle.plan.rank);
192	    let mut sync_secs = 0.0f64;
193	    let mut uploader = WeightUploader::new(ctx, bundle.plan.rank, weight_staging)?;
194	    debug!(
195	        "GLM5.2 rank {} start weight load: tensors={}, shards={}, bytes={}, experts={:?}, uploader={}",
196	        bundle.plan.rank,
197	        bundle.plan.tensor_count,
198	        bundle.shards.len(),
199	        ByteSize(planned_total_bytes as u64),
200	        bundle.plan.expert_range,
201	        uploader.label(),
202	    );
203	
204	    for shard in &bundle.shards {
205	        let path = model_path.join(&shard.shard);
206	        let shard_started = Instant::now();
207	        let mmap = CurrentShardMmap::new(mmap_file(&path)?, ctx, bundle.plan.rank);
208	        let safetensors = safetensors::SafeTensors::deserialize(mmap.as_ref())
209	            .with_context(|| format!("failed to deserialize {}", path.display()))?;
210	        for spec in &shard.tensors {
211	            let view = safetensors
212	                .tensor(&spec.name)
213	                .with_context(|| format!("missing tensor {} in {}", spec.name, path.display()))?;
214	            let contract = expected_tensor_contract(&spec.name)?;
215	            ensure!(
216	                view.dtype() == contract.dtype,
217	                "GLM5.2 tensor {} dtype mismatch: got {:?}, expected {:?}",
218	                spec.name,
219	                view.dtype(),
220	                contract.dtype
221	            );
222	            ensure!(
223	                view.shape() == contract.shape.as_slice(),
224	                "GLM5.2 tensor {} shape mismatch: got {:?}, expected {:?}",
225	                spec.name,
226	                view.shape(),
227	                contract.shape
228	            );
229	            let bytes = view.data().len();
230	            ensure!(
231	                bytes == contract.byte_len()?,
232	                "GLM5.2 tensor {} byte mismatch: got {}, expected {}",
233	                spec.name,
234	                bytes,
235	                contract.byte_len()?
236	            );
237	
238	            if let Some(placement) = expert_placement(&spec.name, &bundle.plan.expert_range)? {
239	                let regions = match weights.expert_layers.entry(placement.layer) {
240	                    std::collections::btree_map::Entry::Occupied(entry) => entry.into_mut(),
241	                    std::collections::btree_map::Entry::Vacant(entry) => entry.insert(
242	                        Glm52ExpertLayerRegions::alloc(ctx, bundle.plan.expert_range.len())?,
243	                    ),
244	                };
245	                let region = regions.region_mut(placement.region);
246	                ensure!(
247	                    placement.offset + bytes <= region.len(),
248	                    "GLM5.2 tensor {} placement [{}..{}) exceeds region {:?} ({} bytes)",
249	                    spec.name,
250	                    placement.offset,
251	                    placement.offset + bytes,
252	                    placement.region,
253	                    region.len()
254	                );
255	                mmap.mark_stream_work();
256	                h2d_copies += uploader
257	                    .upload(ctx, view.data(), region, placement.offset)
258	                    .with_context(|| {
259	                        format!("failed to copy GLM5.2 expert tensor {} to GPU", spec.name)
260	                    })?;
261	                *region_written
262	                    .entry((placement.layer, placement.region))
263	                    .or_default() += bytes;
264	            } else {
265	                // SAFETY: the whole buffer is written by the single H2D copy
266	                // below before it becomes reachable resident state.
267	                let mut dst = unsafe { ctx.stream().alloc::<u8>(bytes) }
268	                    .with_context(|| format!("alloc GLM5.2 tensor {}", spec.name))?;
269	                mmap.mark_stream_work();
270	                h2d_copies += uploader
271	                    .upload(ctx, view.data(), &mut dst, 0)
272	                    .with_context(|| {
273	                        format!("failed to copy GLM5.2 tensor {} to GPU", spec.name)
274	                    })?;
275	                ensure!(
276	                    weights.tensors.insert(spec.name.clone(), dst).is_none(),
277	                    "duplicate GLM5.2 tensor {} in rank {} load plan",
278	                    spec.name,
279	                    bundle.plan.rank,
280	                );
281	            }
282	            weights.total_bytes += bytes;
283	            loaded_total_bytes += bytes;
284	            loaded_tensor_count += 1;
285	        }
286	        drop(safetensors);
287	        sync_secs += mmap_guard.push_completed_shard(mmap.into_mmap())?;
288	        let shard_secs = shard_started.elapsed().as_secs_f64();
289	        match &slowest_shard {
290	            Some((_, slowest_secs)) if *slowest_secs >= shard_secs => {}
291	            _ => slowest_shard = Some((shard.shard.clone(), shard_secs)),
292	        }
293	    }
294	
295	    ensure!(
296	        loaded_tensor_count == bundle.plan.tensor_count,
297	        "GLM5.2 rank {} loaded {loaded_tensor_count} tensors but load plan has {}",
298	        bundle.plan.rank,
299	        bundle.plan.tensor_count
300	    );
301	    ensure!(
302	        loaded_total_bytes == planned_total_bytes,
303	        "GLM5.2 rank {} loaded {} bytes but load plan has {} bytes",
304	        bundle.plan.rank,
305	        loaded_total_bytes,
306	        planned_total_bytes
307	    );
308	    // Every packed expert region must be fully written — a hole here means
309	    // stale device bytes would silently become model weights.
310	    for layer in weights.expert_layers.keys() {
311	        for kind in Glm52ExpertRegionKind::ALL {
312	            let written = region_written.get(&(*layer, kind)).copied().unwrap_or(0);
313	            let expected = kind.region_bytes(bundle.plan.expert_range.len());
314	            ensure!(
315	                written == expected,
316	                "GLM5.2 rank {} layer {layer} expert region {kind:?} incomplete: wrote {written} of {expected} bytes",
317	                bundle.plan.rank
318	            );
319	        }
320	    }
321	    sync_secs += mmap_guard.drain()?;
322	    let uploader_label = uploader.label();
323	    let uploader_drop_started = Instant::now();
324	    drop(uploader);
325	    sync_secs += uploader_drop_started.elapsed().as_secs_f64();
326	    let copy_secs = (copy_started.elapsed().as_secs_f64() - sync_secs).max(0.0);
327	    let sync_started = Instant::now();
328	    ctx.sync().with_context(|| {
329	        format!(
330	            "failed to finish GLM5.2 rank {} H2D tensor copies",
331	            bundle.plan.rank
332	        )
333	    })?;
334	    sync_secs += sync_started.elapsed().as_secs_f64();
335	
336	    let (slowest_shard, slowest_secs) = slowest_shard.unwrap_or_else(|| ("none".to_owned(), 0.0));
337	    info!(
338	        "GLM5.2 rank {} weight load profile: total={:.2}s, mmap_deser_copy={:.2}s, sync={:.2}s, uploader={}, tensors={}, h2d_copies={}, bytes={}, expert_layers={}, slowest_shard={} {:.2}s",
339	        bundle.plan.rank,
340	        load_started.elapsed().as_secs_f64(),
341	        copy_secs,
342	        sync_secs,
343	        uploader_label,
344	        loaded_tensor_count,
345	        h2d_copies,
346	        ByteSize(loaded_total_bytes as u64),
347	        weights.expert_layers.len(),
348	        slowest_shard,
349	        slowest_secs
350	    );
351	
352	    Ok(Glm52RankLoadOutput {
353	        weights,
354	        loaded_tensor_count,
355	        loaded_total_bytes,
356	    })
357	}
