371	impl<'a> CurrentShardMmap<'a> {
372	    fn new(mmap: Mmap, ctx: &'a Glm52RankGpuContext, rank: usize) -> Self {
373	        Self {
374	            mmap: Some(mmap),
375	            ctx,
376	            rank,
377	            stream_work: Cell::new(false),
378	        }
379	    }
380	
381	    fn as_ref(&self) -> &Mmap {
382	        self.mmap.as_ref().expect("current shard mmap is present")
383	    }
384	
385	    fn mark_stream_work(&self) {
386	        self.stream_work.set(true);
387	    }
388	
389	    fn into_mmap(mut self) -> Mmap {
390	        self.stream_work.set(false);
391	        self.mmap.take().expect("current shard mmap is present")
392	    }
393	}
