395	impl Drop for CurrentShardMmap<'_> {
396	    fn drop(&mut self) {
397	        if self.stream_work.get() {
398	            if let Err(error) = self.ctx.set_current().and_then(|()| self.ctx.sync()) {
399	                error!(
400	                    "failed to synchronize GLM5.2 rank {} before dropping current H2D mmap: {error:#}",
401	                    self.rank
402	                );
403	            }
404	        }
405	    }
406	}
