408	struct MmapH2dLifetimeGuard<'a> {
409	    ctx: &'a Glm52RankGpuContext,
410	    rank: usize,
411	    pending_mmaps: Vec<Mmap>,
412	    live_mmap_groups: VecDeque<LiveMmapGroup>,
413	}
414	
415	impl<'a> MmapH2dLifetimeGuard<'a> {
416	    fn new(ctx: &'a Glm52RankGpuContext, rank: usize) -> Self {
417	        Self {
418	            ctx,
419	            rank,
420	            pending_mmaps: Vec::with_capacity(MMAP_EVENT_GROUP),
421	            live_mmap_groups: VecDeque::with_capacity(LIVE_MMAP_GROUPS),
422	        }
423	    }
424	
425	    fn push_completed_shard(&mut self, mmap: Mmap) -> Result<f64> {
426	        self.pending_mmaps.push(mmap);
427	        let mut sync_secs = 0.0;
428	        if self.pending_mmaps.len() == MMAP_EVENT_GROUP {
429	            self.record_pending_group()?;
430	        }
431	        if self.live_mmap_groups.len() >= LIVE_MMAP_GROUPS {
432	            sync_secs += self.wait_oldest_group()?;
433	        }
434	        Ok(sync_secs)
435	    }
436	
437	    fn drain(&mut self) -> Result<f64> {
438	        let mut sync_secs = 0.0;
439	        if !self.pending_mmaps.is_empty() {
440	            self.record_pending_group()?;
441	        }
442	        while !self.live_mmap_groups.is_empty() {
443	            sync_secs += self.wait_oldest_group()?;
444	        }
445	        Ok(sync_secs)
446	    }
447	
448	    fn record_pending_group(&mut self) -> Result<()> {
449	        let event = self.ctx.stream().record_event(None).with_context(|| {
450	            format!(
451	                "failed to record GLM5.2 rank {} H2D mmap group event",
452	                self.rank
453	            )
454	        })?;
455	        let mut mmaps = Vec::with_capacity(MMAP_EVENT_GROUP);
456	        std::mem::swap(&mut self.pending_mmaps, &mut mmaps);
457	        self.live_mmap_groups.push_back(LiveMmapGroup {
458	            _mmaps: mmaps,
459	            event,
460	        });
461	        Ok(())
462	    }
463	
464	    fn wait_oldest_group(&mut self) -> Result<f64> {
465	        let Some(live) = self.live_mmap_groups.front() else {
466	            return Ok(0.0);
467	        };
468	        let started = Instant::now();
469	        live.event.synchronize().with_context(|| {
470	            format!(
471	                "failed to wait for GLM5.2 rank {} H2D mmap event",
472	                self.rank
473	            )
474	        })?;
475	        self.live_mmap_groups.pop_front();
476	        Ok(started.elapsed().as_secs_f64())
477	    }
478	}
479	
480	impl Drop for MmapH2dLifetimeGuard<'_> {
481	    fn drop(&mut self) {
482	        if self.pending_mmaps.is_empty() && self.live_mmap_groups.is_empty() {
483	            return;
484	        }
485	        if let Err(error) = self.ctx.set_current().and_then(|()| self.ctx.sync()) {
486	            error!(
487	                "failed to synchronize GLM5.2 rank {} before dropping H2D mmap guard: {error:#}",
488	                self.rank
489	            );
490	        }
491	    }
492	}
