1	use std::sync::Arc;
2	
3	use anyhow::Context;
4	use anyhow::Result;
5	use anyhow::ensure;
6	use cudarc::driver::CudaContext;
7	use cudarc::driver::CudaStream;
8	
9	#[derive(Clone)]
10	pub(crate) struct Glm52RankGpuContext {
11	    ctx: Arc<CudaContext>,
12	    stream: Arc<CudaStream>,
13	    device_ordinal: usize,
14	}
15	
16	// SAFETY: a GLM5.2 rank owns one CUDA context/stream pair. The worker binds it
17	// to its thread before touching device state.
18	unsafe impl Send for Glm52RankGpuContext {}
19	unsafe impl Sync for Glm52RankGpuContext {}
20	
21	impl Glm52RankGpuContext {
22	    pub(crate) fn new(device_ordinal: usize) -> Result<Self> {
23	        let ctx = CudaContext::new(device_ordinal)
24	            .with_context(|| format!("create GLM5.2 CUDA context for device {device_ordinal}"))?;
25	        ctx.bind_to_thread()
26	            .with_context(|| format!("bind GLM5.2 CUDA context for device {device_ordinal}"))?;
27	        retain_async_alloc_pool(device_ordinal)?;
28	        unsafe {
29	            ctx.disable_event_tracking();
30	        }
31	        let stream = ctx
32	            .new_stream()
33	            .with_context(|| format!("create GLM5.2 CUDA stream for device {device_ordinal}"))?;
34	        Ok(Self {
35	            ctx,
36	            stream,
37	            device_ordinal,
38	        })
39	    }
40	
41	    pub(crate) fn set_current(&self) -> Result<()> {
42	        self.ctx.bind_to_thread().with_context(|| {
43	            format!(
44	                "bind GLM5.2 CUDA context for device {} to current thread",
45	                self.device_ordinal
46	            )
47	        })
48	    }
49	
50	    /// This rank's device free VRAM. Re-binds the rank's context first so
51	    /// the query reads THIS device regardless of what the calling thread
52	    /// happened to have current — the number sizes every rank's cache
53	    /// arenas, so a wrong-device read must be unrepresentable.
54	    pub(crate) fn free_vram_bytes(&self) -> Result<usize> {
55	        self.set_current()?;
56	        let (free, _total) = cudarc::driver::result::mem_get_info()
57	            .map_err(|err| anyhow::anyhow!("cuMemGetInfo failed: {err:?}"))?;
58	        Ok(free)
59	    }
60	
61	    pub(crate) fn sync(&self) -> Result<()> {
62	        self.stream
63	            .synchronize()
64	            .with_context(|| format!("synchronize GLM5.2 device {}", self.device_ordinal))
65	    }
66	
67	    pub(crate) fn stream(&self) -> &Arc<CudaStream> {
68	        &self.stream
69	    }
70	
71	    pub(crate) fn cuda_context(&self) -> &Arc<CudaContext> {
72	        &self.ctx
73	    }
74	
75	    /// The kernels-crate view of this rank's context/stream pair (shared
76	    /// Arcs, not a new context) — what the forward bricks take. Also performs
77	    /// the kernels-crate per-thread setup that `DeviceContext::new` would do:
78	    /// the cuBLAS handle is thread-local per device, so the calling worker
79	    /// thread must initialize its own (idempotent).
80	    pub(crate) fn device_context(&self) -> Result<pegainfer_kernels::tensor::DeviceContext> {
81	        // SAFETY: plain device selection + idempotent handle creation.
82	        unsafe {
83	            let err = pegainfer_kernels::ffi::cuda_set_device(self.device_ordinal as i32);
84	            ensure!(
85	                err == 0,
86	                "GLM5.2 cudaSetDevice({}) failed: cudaError={err}",
87	                self.device_ordinal
88	            );
89	            pegainfer_kernels::ffi::cublas_init();
90	        }
91	        Ok(pegainfer_kernels::tensor::DeviceContext {
92	            ctx: self.ctx.clone(),
93	            stream: self.stream.clone(),
94	            device_ordinal: self.device_ordinal,
95	        })
96	    }
97	
98	    /// A second stream on the same context, for work that overlaps the main
99	    /// stream inside the decode step (fork/join via events — the shared
100	    /// expert runs concurrently with the MoE collectives).
101	    pub(crate) fn auxiliary_device_context(
102	        &self,
103	        role: &str,
104	    ) -> Result<pegainfer_kernels::tensor::DeviceContext> {
105	        use anyhow::Context as _;
106	        let stream = self.ctx.new_stream().with_context(|| {
107	            format!(
108	                "failed to create GLM5.2 {role} stream for device {}",
109	                self.device_ordinal
110	            )
111	        })?;
112	        Ok(pegainfer_kernels::tensor::DeviceContext {
113	            ctx: self.ctx.clone(),
114	            stream,
115	            device_ordinal: self.device_ordinal,
116	        })
117	    }
118	}
119	
120	fn retain_async_alloc_pool(device_ordinal: usize) -> Result<()> {
121	    use cudarc::driver::sys;
122	    unsafe {
123	        let mut dev: sys::CUdevice = 0;
124	        check_cu(
125	            sys::cuDeviceGet(&raw mut dev, device_ordinal as i32),
126	            "cuDeviceGet",
127	        )?;
128	        let mut pool: sys::CUmemoryPool = std::ptr::null_mut();
129	        check_cu(
130	            sys::cuDeviceGetDefaultMemPool(&raw mut pool, dev),
131	            "cuDeviceGetDefaultMemPool",
132	        )?;
133	        let mut threshold: u64 = u64::MAX;
134	        check_cu(
135	            sys::cuMemPoolSetAttribute(
136	                pool,
137	                sys::CUmemPool_attribute_enum::CU_MEMPOOL_ATTR_RELEASE_THRESHOLD,
138	                (&raw mut threshold).cast::<std::ffi::c_void>(),
139	            ),
140	            "cuMemPoolSetAttribute(RELEASE_THRESHOLD)",
141	        )?;
142	    }
143	    Ok(())
144	}
145	
146	fn check_cu(result: cudarc::driver::sys::CUresult, what: &str) -> Result<()> {
147	    ensure!(
148	        result == cudarc::driver::sys::CUresult::CUDA_SUCCESS,
149	        "GLM5.2 {what} failed: {result:?}"
150	    );
151	    Ok(())
152	}
